import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Webpack 工程化","description":"Webpack 是前端工程化的核心构建工具之一。本专题提供由浅及深的系统化文档,","frontmatter":{},"headers":[],"relativePath":"工程化/webpack/index.md","filePath":"工程化/webpack/index.md","lastUpdated":1793930980000}'),i={name:"工程化/webpack/index.md"};function t(n,e,s,c,d,p){return r(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="webpack-工程化" tabindex="-1">Webpack 工程化 <a class="header-anchor" href="#webpack-工程化" aria-label="Permalink to &quot;Webpack 工程化&quot;">​</a></h1><blockquote><p>Webpack 是前端工程化的核心构建工具之一。本专题提供<strong>由浅及深</strong>的系统化文档,</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-webpack">Webpack 是什么</a> — 解决了什么问题、生态定位、核心理念</li><li><a href="./2-build-process">构建流程</a> — 从 entry 到 bundle 的完整生命周期</li><li><a href="./3-loader">Loader</a> — 文件转换机制,常用 Loader 实战</li><li><a href="./4-plugin">Plugin</a> — 编译时钩子,常用 Plugin 实战</li><li><a href="./5-loader-vs-plugin">Loader vs Plugin 对比</a> — 区别 + 编写思路</li><li><a href="./6-hmr">HMR 热更新</a> — 原理 + 配置 + 注意事项</li><li><a href="./7-devserver-proxy">DevServer Proxy</a> — 跨域代理工作原理</li><li><a href="./8-build-speed">构建速度优化</a> — 减少构建时间(实战数据)</li><li><a href="./9-bundle-size">产物体积优化</a> — 减小 bundle、tree shaking、code splitting</li><li><a href="./10-ecosystem">构建工具生态</a> — Webpack vs Rollup vs Parcel vs Vite vs esbuild</li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>Webpack 的核心是<strong>模块化打包</strong>:把依赖图里的所有模块按规则转换成资源并输出为静态文件。</li><li>必须理解的四件事:<strong>entry/dependency graph</strong>(依赖图如何生成)、<strong>loader</strong>(把非 JS 文件转成模块)、<strong>plugin</strong>(在编译生命周期挂钩子)、<strong>chunk 与 splitChunks</strong>(分包策略)。</li><li>构建流程:解析配置 → 建立模块依赖图 → loader 转换 → 模块转成 chunk → chunk 优化(tree shaking、压缩)→ 输出。</li><li>优化两大方向:<strong>构建速度</strong>(缓存、持久化、<code>thread-loader</code>、缩小 include、关掉 source-map 生产版)与<strong>产物体积</strong>(按 <code>splitChunks</code> 分 vendor、动态 import、tree shaking 需 <code>sideEffects: false</code>)。</li><li>面试常问:loader 与 plugin 的区别(前者转换模块内容,后者介入编译流程);<code>splitChunks</code> 的 <code>chunks</code>/<code>cacheGroups</code> 配置含义。</li><li>现在虽然新项目多用 Vite,但<strong>读懂 Webpack 能让你理解模块图、分包、预构建这些底层概念</strong>。</li></ul>',6)])])}const k=a(i,[["render",t]]);export{u as __pageData,k as default};
